sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float cornerRadius;
uniform float inset;
uniform float smoothing;
uniform float borderWidth;
layout(color) uniform half4 borderColor;
uniform float glowSize;
uniform float glowAmount;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float2 p = coord - size * 0.5;
    float2 halfSize = size * 0.5 - float2(inset);
    float rad = min(cornerRadius, min(halfSize.x, halfSize.y));
    float2 q = abs(p) - halfSize + float2(rad);
    float sd = length(max(q, float2(0.0))) + min(max(q.x, q.y), 0.0) - rad;
    float m = 1.0 - smoothstep(-smoothing * 0.5, smoothing * 0.5, sd);
    float ring = m * smoothstep(-borderWidth - smoothing * 0.5, -borderWidth + smoothing * 0.5, sd) * step(0.01, borderWidth);
    float g = exp(-max(sd, 0.0) / max(glowSize, 0.001)) * (1.0 - m) * glowAmount * step(0.01, glowSize);
    float3 col = mix(s, float3(borderColor.rgb), ring);
    float a = max(c.a * m, g);
    float3 o = mix(col, float3(borderColor.rgb), g * (1.0 - m));
    return fin(c, float4(max(o, float3(0.0)) * a, a), opacity);
}
